  this.a9T = "Spo\u0142eczno\u015bci tutaj";
  this.abl = "jeszcze \u017cadnej";
  this.adO = "U\u017cyj tego adresu";
  this.aa1 = "Utw\u00f3rz spo\u0142eczno\u015b\u0107";
  this.aa2 = "Zostajesz jej za\u0142o\u017cycielem: klucz Twojego urz\u0105dzenia otwiera w\u0142asne konto spo\u0142eczno\u015bci, a z niego przyjmujesz uczestnik\u00f3w i ustalasz ich limity. Nikt inny ni\u0105 nie zarz\u0105dza.";
  this.acq = "Jej miejsce w adresie";
  this.acs = "ma\u0142e litery, cyfry, \u0142\u0105czniki: nasze-miasto";
  this.adK = "Jednostka (waluta krajowa, w kt\u00f3rej si\u0119 liczy)";
  this.aav = "Jak si\u0119 do\u0142\u0105cza";
