  this.a9a = "Przyj\u0119to";
  this.acP = "Odrzucono";
  this.abB = "Nie przyj\u0119to";
  this.act = "To miejsce jest zaj\u0119te: wybierz inne.";
  this.acr = "Miejsce to od 3 do 40 ma\u0142ych liter, cyfr lub \u0142\u0105cznik\u00f3w; jednostka \u2014 litery.";
  this.aay = "Dzi\u015b nie mo\u017cna st\u0105d utworzy\u0107 wi\u0119cej spo\u0142eczno\u015bci.";
  this.aaw = "Tutaj spo\u0142eczno\u015bci nie tworzy ka\u017cdy: zapytaj operatora tej strony.";
  this.a9d = "Inna spo\u0142eczno\u015b\u0107";
  this.adL = "Jednostka";
  this.acg = "Do innej spo\u0142eczno\u015bci";
  this.adW = "Do kt\u00f3rej spo\u0142eczno\u015bci";
  this.abv = "W tamtej spo\u0142eczno\u015bci nie ma jeszcze komu p\u0142aci\u0107.";
  this.adE = "Linie zaufania";
  this.aaU = "Linia zaufania m\u00f3wi, ile inna spo\u0142eczno\u015b\u0107 mo\u017ce by\u0107 winna naszej. Wtedy jej uczestnicy mog\u0105 p\u0142aci\u0107 naszym, a nasi \u2014 jej uczestnikom, na ile ONA ufa nam. Saldo dodatnie: winni jeste\u015bmy my; ujemne: winni s\u0105 nam.";
  this.ady = "Mog\u0105 by\u0107 nam winni";
  this.abn = "nie ma jeszcze linii";
