  this.akc = "\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0449\u0435 \u0440\u0430\u0437";
  this.aor = "\u0417\u0430\u0431\u0443\u0442\u0438 \u0446\u044e \u0437\u0430\u044f\u0432\u043a\u0443";
  this.ani = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.alT = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.ajA = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.ang = "\u0412\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.ajC = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.anh = "\u0412\u0456\u0434\u0445\u0438\u043b\u0435\u043d\u043e";
  this.am3 = "\u041d\u0435 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.amV = "\u0426\u0435 \u043c\u0456\u0441\u0446\u0435 \u0437\u0430\u0439\u043d\u044f\u0442\u0435: \u043e\u0431\u0435\u0440\u0456\u0442\u044c \u0456\u043d\u0448\u0435.";
  this.amT = "\u0423 \u043c\u0456\u0441\u0446\u0456 \u2014 \u0432\u0456\u0434 3 \u0434\u043e 40 \u043c\u0430\u043b\u0438\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u044c\u043a\u0438\u0445 \u043b\u0456\u0442\u0435\u0440, \u0446\u0438\u0444\u0440 \u0430\u0431\u043e \u0434\u0435\u0444\u0456\u0441\u0456\u0432; \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043b\u0456\u0442\u0435\u0440\u0438.";
  this.al0 = "\u0421\u044c\u043e\u0433\u043e\u0434\u043d\u0456 \u0437\u0432\u0456\u0434\u0441\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.akY = "\u0422\u0443\u0442 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u0435 \u043a\u043e\u0436\u0435\u043d: \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0446\u044c\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0443.";
  this.ajF = "\u0406\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430";
  this.aod = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f";
  this.amI = "\u0414\u043e \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aoo = "\u0414\u043e \u044f\u043a\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.alX = "\u0423 \u0442\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0456\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
  this.ao6 = "\u041b\u0456\u043d\u0456\u0457 \u0434\u043e\u0432\u0456\u0440\u0438";
  this.alm = "\u041b\u0456\u043d\u0456\u044f \u0434\u043e\u0432\u0456\u0440\u0438 \u043a\u0430\u0436\u0435, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0456\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043d\u0430\u0448\u0456\u0439. \u0422\u043e\u0434\u0456 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0456 \u2014 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0412\u041e\u041d\u0410 \u0434\u043e\u0432\u0456\u0440\u044f\u0454 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456: \u0432\u0438\u043d\u043d\u0456 \u043c\u0438; \u043c\u0456\u043d\u0443\u0441: \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c.";
  this.ao0 = "\u041c\u043e\u0436\u0443\u0442\u044c \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c";
  this.alP = "\u043b\u0456\u043d\u0456\u0439 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0435\u043c\u0430\u0454";
  this.amz = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u043b\u0456\u043d\u0456\u044e";
  this.alg = "\u0410\u0434\u0440\u0435\u0441\u0430 \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.alh = "\u044f\u043a \u0443 \u0457\u0457 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u0456-\u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u0456 \u043f\u0456\u0441\u043b\u044f ?node=";
  this.aka = "\u0417\u043c\u0456\u043d\u0438\u0442\u0438";
  this.alj = "\u041b\u0456\u043d\u0456\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.ali = "\u041b\u0456\u043d\u0456\u044e \u043d\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.all = "\u0422\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0440\u0430\u0445\u0443\u0454 \u0432 \u0456\u043d\u0448\u0456\u0439 \u043e\u0434\u0438\u043d\u0438\u0446\u0456: \u043b\u0456\u043d\u0456\u0457 \u043c\u0456\u0436 \u0440\u0456\u0437\u043d\u0438\u043c\u0438 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438 \u0449\u0435 \u043d\u0435 \u0437\u0440\u043e\u0431\u043b\u0435\u043d\u043e.";
  this.alW = "\u0417\u0430 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454.";
  this.alk = "\u0426\u0435 \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430.";
  this.aop = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u0438";
  this.ajV = "\u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0456 (\u043d\u0430\u0439\u043f\u0440\u043e\u0441\u0442\u0456\u0448\u0435)";
  this.amK = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u044f\u043a\u0456 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e)";
  this.amJ = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u0432 \u0443\u0441\u0456\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0456 \u043b\u0456\u043d\u0456\u0457";
  this.amC = "\u0412\u0430\u0448 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u043d\u0443\u043b\u044f \u0439 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0449\u043e\u0441\u044c \u0430\u0431\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0439\u0442\u0435 \u0440\u043e\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430 \u2014 \u0456 \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u0435\u043d\u0435.";
  this.alO = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u0438\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0442\u0438.";
  this.anp = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.ano = "\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0442\u0435\u043a\u0441\u0442: \u0439\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043a\u043e\u0436\u0435\u043d \u043d\u043e\u0432\u0430\u0447\u043e\u043a. \u041f\u0435\u0440\u0448 \u043d\u0456\u0436 \u043d\u0430 \u043d\u044c\u043e\u0433\u043e \u043f\u043e\u043a\u043b\u0430\u0434\u0430\u0442\u0438\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0456\u0442\u044c \u0439\u043e\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u043e\u0432\u0456.";
  this.anO = "1. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0435\u0434\u0435 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u043e\u0433\u043e, \u0449\u043e \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442\u044c \u043e\u0434\u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0439 \u0431\u0435\u0440\u0443\u0442\u044c \u043e\u0434\u043d\u0435 \u0432 \u043e\u0434\u043d\u043e\u0433\u043e. \u041e\u0434\u0438\u043d\u0438\u0446\u044f \u2014 \u043c\u0456\u0440\u0430 \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443; \u0443 \u0446\u0456\u043d\u0430\u0445 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u043e\u0434\u043d\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0457 \u0432\u0430\u043b\u044e\u0442\u0438.\n2. \u041e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043d\u0435 \u0433\u0440\u043e\u0448\u0456. \u041d\u0456\u0445\u0442\u043e \u0439 \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454, \u043d\u0435 \u043a\u0443\u043f\u0443\u0454 \u0456 \u043d\u0435 \u043e\u0431\u043c\u0456\u043d\u044e\u0454 \u0457\u0445 \u043d\u0430 \u0433\u0440\u043e\u0448\u0456.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u0438\u0449\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0434\u0430\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0443\u0437\u044f\u0432; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0432\u0456\u043d \u0443\u0437\u044f\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0434\u0430\u0432, \u0456 \u043c\u0430\u0454 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u0441\u0432\u043e\u0457\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0443 \u043b\u0456\u043d\u0456\u044e \u0456 \u0441\u0442\u0435\u043b\u044e; \u0457\u0445 \u0437\u0430\u0434\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0439 \u043c\u043e\u0436\u0435 \u0437\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438.\n5. \u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u0456 \u0432\u043e\u043d\u0430 \u0437\u043d\u0430\u0454 \u0457\u0445 \u0437\u0430 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c\u0438 \u0456\u043c\u0435\u043d\u0430\u043c\u0438.\n6. \u041f\u0440\u043e\u0434\u0430\u0436 \u0437\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u0438\u0441\u0442\u0430\u0432\u043b\u044f\u0454 \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439 \u0441\u0430\u043c \u0441\u043f\u043b\u0430\u0447\u0443\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u0438, \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u044f\u043a \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0443.\n7. \u0423\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u043e\u0436\u0435 \u0432\u0438\u0439\u0442\u0438 \u0431\u0443\u0434\u044c-\u043a\u043e\u043b\u0438, \u0437\u0432\u0456\u0432\u0448\u0438 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u043d\u0443\u043b\u044f. \u0422\u043e\u0439, \u0445\u0442\u043e \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u0437 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f, \u043f\u043e\u0433\u0430\u0448\u0430\u0454 \u0440\u0456\u0437\u043d\u0438\u0446\u044e \u0433\u0440\u043e\u0448\u0438\u043c\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 30 \u0434\u043d\u0456\u0432.\n8. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u043e\u0440\u0443\u0448\u0443\u0454 \u0446\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.aji = "\u041f\u0440\u0438\u0439\u043c\u0430\u044e";
  this.anm = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.anq = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.ann = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0437\u043c\u0456\u043d\u0438\u043b\u0438\u0441\u044f: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0456 \u043f\u0440\u0438\u0439\u043c\u0456\u0442\u044c \u0457\u0445 \u0437\u043d\u043e\u0432\u0443.";
  this.amu = "\u0426\u044f \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0438\u0445.";
  this.aks = "\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u0432\u0438\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.anP = "\u0421\u043a\u043e\u043f\u0456\u0439\u043e\u0432\u0430\u043d\u043e";
  this.anQ = "\u0412\u0430\u0448\u0456 \u0443\u0433\u043e\u0434\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0456 \u043e\u0431\u043c\u0456\u043d\u0443 \u0443 \u0432\u0438\u0433\u043b\u044f\u0434\u0456 CSV: \u0432\u0441\u0442\u0430\u0432\u0442\u0435 \u0457\u0445 \u0443 \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0430\u0431\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u043e\u0432\u0456. \u0423\u0433\u043e\u0434\u0430 \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u0445 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436, \u0432\u0456\u043d \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0439 \u043e\u043f\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0456\u043d\u0448\u0438\u0439.";
  this.am6 = "\u0426\u0435\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0454 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438. \u0412\u0438\u0434\u0456\u043b\u0456\u0442\u044c \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0456 \u0441\u043a\u043e\u043f\u0456\u044e\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443.";
  this.aln = "\u042f \u0432\u0442\u0440\u0430\u0442\u0438\u0432(\u043b\u0430) \u0441\u0432\u043e\u0457 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457";
  this.alo = "\u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a. \u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u043d\u043e\u0432\u0438\u0439 \u043a\u043b\u044e\u0447 \u0456 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0432\u0430\u0448\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438, \u0449\u043e \u0446\u0435 \u0432\u0438. \u041f\u0456\u0441\u043b\u044f \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u043a\u043b\u044e\u0447 \u0442\u0440\u0438\u043c\u0430\u0442\u0438\u043c\u0435 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0447\u0435\u0440\u0435\u0437 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u2014 \u0447\u0430\u0441, \u0449\u043e\u0431 \u0432\u0438 \u0432\u0441\u0442\u0438\u0433\u043b\u0438 \u0432\u0456\u0434\u043c\u043e\u0432\u0438\u0442\u0438, \u044f\u043a\u0449\u043e \u043f\u0440\u043e\u0441\u0438\u0432 \u0445\u0442\u043e\u0441\u044c \u0456\u043d\u0448\u0438\u0439.";
  this.al7 = "\u0426\u0435 \u043c\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ajI = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.amm = "\u0429\u0435 \u043d\u0456: \u0441\u0442\u0440\u043e\u043a \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0435 \u043c\u0438\u043d\u0443\u0432.";
  this.ajN = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.akJ = "\u0417\u0430\u0431\u0443\u0442\u0438";
  this.ak3 = "\u0426\u0435 \u043d\u0435 \u044f: \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438";
  this.ane = "\u0421\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e: \u0442\u043e\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0454.";
  this.anc = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.anb = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0439\u0442\u0435, \u043b\u0438\u0448\u0435 \u044f\u043a\u0449\u043e \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0456, \u0449\u043e \u0446\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0456\u0442\u044c \u0456\u0437 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044e. \u0421\u0442\u0430\u0440\u0456 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u0449\u0435 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043c\u043e\u0436\u0443\u0442\u044c \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.";
  this.alS = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u044c";
  this.akq = "\u0426\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438";
  this.and = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043e";
  this.akA = "\u041d\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u0432\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.ajP = "\u0414\u043e\u0448\u043a\u0430";
  this.ajT = "\u0429\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0456 \u0449\u043e \u0448\u0443\u043a\u0430\u044e\u0442\u044c. \u0426\u0456\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0456\u0439 \u0432\u0430\u043b\u044e\u0442\u0456; \u0447\u0430\u0441\u0442\u043a\u0430 \u043a\u0430\u0436\u0435, \u044f\u043a\u0430 \u0457\u0457 \u0447\u0430\u0441\u0442\u0438\u043d\u0430 \u0431\u0435\u0440\u0435\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043b\u0430\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u043f\u043e\u0437\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u044e.";
  this.ajS = "\u0412\u0438\u0434";
  this.amr = "\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454";
  this.aom = "\u0448\u0443\u043a\u0430\u0454";
  this.ajQ = "\u043f\u043e\u043a\u0438 \u0449\u043e \u043f\u043e\u0440\u043e\u0436\u043d\u044c\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0448\u0438\u043c";
  this.amy = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438";
  this.aju = "\u041f\u0440\u043e\u043f\u043e\u043d\u0443\u044e";
  this.ajx = "\u0428\u0443\u043a\u0430\u044e";
  this.akD = "\u0414\u043e\u043a\u043b\u0430\u0434\u043d\u0456\u0448\u0435";
  this.an4 = "\u0426\u0456\u043d\u0430";
  this.an5 = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.ajX = "\u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.al2 = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, %";
  this.al3 = "\u044f\u043a\u0443 \u0447\u0430\u0441\u0442\u043a\u0443 \u0446\u0456\u043d\u0438 \u0432\u0438 \u0431\u0435\u0440\u0435\u0442\u0435 \u0430\u0431\u043e \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438: 100 \u2014 \u0443\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
  this.anz = "\u0432\u0456\u0434 0 \u0434\u043e 100";
  this.an3 = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f \u043d\u0430 \u0434\u043e\u0448\u0446\u0456";
  this.amd = "\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f";
  this.ajR = "\u041d\u0430 \u0434\u043e\u0448\u0446\u0456 \u043d\u0435\u043c\u0430\u0454 \u043c\u0456\u0441\u0446\u044f \u0434\u043b\u044f \u0449\u0435 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u043e\u0433\u043e \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u043d\u0456\u043c\u0456\u0442\u044c \u043e\u0434\u043d\u0435.";
  this.anX = "\u0417\u043d\u044f\u0442\u0438 \u0437 \u0434\u043e\u0448\u043a\u0438";
  this.anA = "\u0421\u043f\u0456\u043b\u044c\u043d\u0456 \u0440\u0430\u0445\u0443\u043d\u043a\u0438";
  this.anG = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0440\u043e\u0434\u0438\u043d\u0438 \u0447\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0438 \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0430 \u043d\u0435 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457: \u043a\u043e\u0436\u0435\u043d \u0442\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0438\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e, \u0430 \u0432\u0442\u0440\u0430\u0447\u0435\u043d\u0438\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0443 \u0432\u043b\u0430\u0441\u043d\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043b\u044e\u0434\u0438\u043d\u0438.";
  this.alU = "\u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0440\u0430\u0445\u0443\u043d\u043a\u0456\u0432 \u043f\u043e\u043a\u0438 \u043d\u0435\u043c\u0430\u0454";
  this.alG = "\u041d\u043e\u0432\u0438\u0439 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.anC = "\u041d\u0430\u0437\u0432\u0430";
  this.anD = "\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432.";
  this.anF = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e, \u0432\u0438 \u0439\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447. \u0412\u043b\u0430\u0441\u043d\u043e\u0457 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u043d \u043d\u0435 \u043c\u0430\u0454: \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0454 \u0442\u0435, \u0449\u043e \u0439\u043e\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0430\u0431\u043e \u043b\u0456\u043d\u0456\u044e, \u044f\u043a\u0443 \u0439\u043e\u043c\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a. \u0406\u043d\u0448\u0438\u0445 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0432 \u0440\u043e\u0437\u0434\u0456\u043b\u0456 \u00ab\u0422\u0440\u0438\u043c\u0430\u0447\u0456\u00bb.";
  this.akT = "\u0422\u0440\u0438\u043c\u0430\u0447\u0456";
  this.akU = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0434\u0456\u044f\u0442\u0438 \u0432\u0456\u0434 \u0456\u043c\u0435\u043d\u0456 \u0446\u044c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443: \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0443 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u2014 \u0449\u043e \u0432\u0456\u043d \u043c\u043e\u0436\u0435 \u0456 \u0441\u043a\u0456\u043b\u044c\u043a\u0438. \u0422\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u0440\u0430\u0445\u0443\u043d\u043a\u043e\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e.";
  this.ajt = "\u0414\u043e\u0434\u0430\u0442\u0438 \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.akS = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
  this.aot = "\u0432\u0438";
  this.ao9 = "\u0414\u0432\u0430 \u043f\u0456\u0434\u043f\u0438\u0441\u0438";
  this.ao7 = "\u0414\u0432\u0430 \u0442\u0440\u0438\u043c\u0430\u0447\u0456 \u0434\u043b\u044f \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u043d\u0430\u0434";
  this.ao8 = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aob = "\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
  this.aoa = "\u0422\u0435\u043f\u0435\u0440 \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430.";
  this.ao5 = "\u041f\u043b\u0430\u0442\u0435\u0436\u0456, \u0449\u043e \u0447\u0435\u043a\u0430\u044e\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.ao4 = "\u041f\u043b\u0430\u0442\u0456\u0436 \u043f\u043e\u043d\u0430\u0434 \u043f\u043e\u0440\u0456\u0433 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043e\u0434\u0438\u043d \u0442\u0440\u0438\u043c\u0430\u0447, \u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0456\u043d\u0448\u0438\u0439. \u041d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043f\u043b\u0430\u0442\u0456\u0436 \u0432\u0456\u0434\u043f\u0430\u0434\u0430\u0454.";
  this.amp = "\u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.akr = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438";
  this.an7 = "\u0417\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u0432";
  this.an6 = "\u041f\u043b\u0430\u0442\u0456\u0436 \u0447\u0435\u043a\u0430\u0454 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.alA = "\u0426\u0435\u0439 \u043f\u043b\u0430\u0442\u0456\u0436 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u043b\u0438 \u0432\u0438: \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u0430\u0454 \u0456\u043d\u0448\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.alB = "\u0426\u044c\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u0442\u0440\u0456\u0431\u0435\u043d \u0434\u0440\u0443\u0433\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.amW = "\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430";
  this.an2 = "\u0412\u043b\u0430\u0441\u043d\u0430 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0434\u0456\u0454 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443. \u041b\u0456\u043d\u0456\u0457, \u0432\u0438\u0434\u0430\u043d\u0456 \u0440\u0430\u043d\u0456\u0448\u0435, \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u044f\u043a \u0454. \u0425\u0430\u0431, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u0441\u0442\u043e\u0457\u0442\u044c \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u043c\u043e\u0436\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0442\u0438 \u043c\u0435\u043d\u0448\u0435, \u043d\u0456\u0436 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0434\u0435\u0456\u043d\u0434\u0435.";
  this.amY = "\u0412\u0441\u0442\u0443\u043f \u0456 \u0431\u0456\u0437\u043d\u0435\u0441\u0438";
  this.amZ = "\u041f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438";
  this.an0 = "\u041a\u0440\u0435\u0434\u0438\u0442 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456\u0439 \u043e\u0441\u043e\u0431\u0456, \u043d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437\u0432\u0456\u0434\u0441\u043e\u0442\u043a\u043e\u0432\u0438\u0439, \u043c\u043e\u0436\u0435 \u043f\u0456\u0434\u043f\u0430\u0434\u0430\u0442\u0438 \u043f\u0456\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0443. \u0414\u0435 \u043b\u044e\u0434\u0438 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u0438\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043d\u0435 \u0432\u0438\u043d\u0438\u043a\u0430\u0454.";
  this.amM = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0438\u0448\u0435 \u0437 \u043b\u0456\u043d\u0456\u0454\u044e, \u044f\u043a\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a";
  this.amL = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0456\u043d\u0456\u044f \u043f\u0456\u0441\u043b\u044f \u0442\u043e\u0433\u043e, \u044f\u043a \u043b\u044e\u0434\u0438\u043d\u0430 \u0437\u0430\u0440\u043e\u0431\u0438\u043b\u0430";
  this.amN = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u043d\u043e\u0432\u043e\u0457 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438";
  this.amO = "\u0442\u0430\u043c, \u0434\u0435 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u043c\u0430\u044e\u0442\u044c \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u0434 \u043f\u043e\u0447\u0430\u0442\u043a\u0443";
  this.amP = "\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u0449\u043e\u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043b\u044e\u0434\u0438\u043d\u0430";
  this.amQ = "\u0432\u043b\u0430\u0441\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u0439 \u043f\u043e\u0437\u0438\u0447\u0435\u043d\u0430 \u0440\u0430\u0437\u043e\u043c; \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0431\u0435\u0437 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f";
