  this.akC = "\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u043b\u044e\u0434\u0438\u043d\u0456 \u043c\u0430\u043b\u0438 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0434\u0430\u0441\u0442\u044c \u043b\u0456\u043d\u0456\u044e";
